// Example of measuring event loop latency
function measureEventLoopLatency() {
  performance.mark('loopStart');
  setTimeout(() => {
    performance.mark('loopEnd');
    performance.measure('loopLatency', 'loopStart', 'loopEnd');
    const measurement = performance.getEntriesByName('loopLatency')[0];
    console.log(`Event loop latency: ${measurement.duration.toFixed(2)}ms`);
  }, 0);
}

